// План specs/multi-business.md 1.4 (кейс MB-04). Две роли: владелец (admin) находит JOB-1036 в Onsite и берёт её адрес,
// диспетчер «test» открывает этот адрес напрямую. @prod-safe: только просмотр. В конце оба окна возвращаются на «test».
import { test, expect } from '../../fixtures';
import {
  DATA, ONSITE_COMPANY, TEST_COMPANY, expectSelected, jobRow, openJobs, restoreTest, search, startInTest, switchTo,
} from './business-helpers';

test.describe('Multi-business: direct URL to another business job (#04d339)', () => {
  test('Dispatcher of test opens Onsite job JOB-1036 by direct URL and is silently redirected to /Jobs #04d339 @desktop @prod-safe', async ({ asUser }) => {
    const owner = await asUser('admin');
    const dispatcher = await asUser('dispatcher');
    await startInTest(owner);
    await startInTest(dispatcher);
    let jobUrl = '';
    try {
      // Владелец: Onsite → Jobs → поиск «QA-B2» → открыть JOB-1036 (только просмотр) → адрес работы.
      await owner.goto('/dashboard');
      await switchTo(owner, ONSITE_COMPANY.name);
      await openJobs(owner);
      await search(owner, DATA.onsiteSearch);
      await jobRow(owner, DATA.onsiteJob).click();
      await owner.waitForURL(/\/JobDetail\?id=[0-9a-f-]{36}/i, { timeout: 30_000 });
      jobUrl = new URL(owner.url()).pathname + new URL(owner.url()).search;
      await expect(owner.locator('main')).toContainText(DATA.onsiteClient.replace(/ client$/, ''));
    } finally {
      await restoreTest(owner);
    }

    try {
      // Диспетчер «test»: прямой адрес работы Onsite → тихий редирект на /Jobs, данных JOB-1036 нет
      // (источник: FL-18 «חסימת שיוך לעסק שאין גישה אליו»; AC «מנהל עסק א' חסום מעסק ב'»).
      await dispatcher.goto(jobUrl);
      await dispatcher.waitForURL(/\/jobs\/?(\?.*)?$/i, { timeout: 30_000 });
      await expectSelected(dispatcher, TEST_COMPANY.name);
      await expect(dispatcher.locator('main')).toContainText(/JOB-\d{4}/, { timeout: 30_000 });
      await expect(jobRow(dispatcher, DATA.onsiteJob)).toHaveCount(0);
      await expect(dispatcher.getByText(DATA.onsiteClient)).toHaveCount(0);
    } finally {
      await restoreTest(dispatcher);
    }
  });
});
